async function put(id,parent,x,y,w,h){const c=await figma.getNodeByIdAsync(id);const i=c.createInstance();parent.appendChild(i);i.x=x;i.y=y;if(w&&h){try{i.resize(w,h)}catch(e){}}return i;}
function tint(n,c){try{if('fills' in n&&n.fills&&n.fills.length)n.fills=[{type:'SOLID',color:c}]}catch(e){}if('children' in n)n.children.forEach(k=>tint(k,c));}
function rect(p,x,y,w,h,f,r=0){const s=figma.createRectangle();p.appendChild(s);s.x=x;s.y=y;s.resize(w,h);if(f)s.fills=[{type:'SOLID',color:f}];else s.fills=[];if(r)s.cornerRadius=r;return s;}
function txt(p,ch,x,y,w,o={}){const t=figma.createText();p.appendChild(t);t.fontName={family:o.fam||'Poppins',style:o.style||'Regular'};t.characters=ch;t.fontSize=o.size||14;t.fills=[{type:'SOLID',color:o.color||INK}];t.x=x;t.y=y;t.textAutoResize='HEIGHT';t.resize(w,t.height);if(o.align)t.textAlignHorizontal=o.align;if(o.lh)t.lineHeight={unit:'PIXELS',value:o.lh};return t;}
function frame(name,x,y,h=874){const f=figma.createFrame();f.name=name;f.x=x;f.y=y;f.resize(402,h);f.fills=[{type:'SOLID',color:WHITE}];f.clipsContent=true;page.appendChild(f);return f;}
async function shell(f,dark){const sb=await put('1:33',f,0,0);if(dark)tint(sb,WHITE);const hi=await put('1:43',f,0,840);if(dark)tint(hi,WHITE);}
function cmpByName(n){return page.findOne(x=>x.type==='COMPONENT'&&x.name===n);}
function instC(cmp,parent,x,y){const i=cmp.createInstance();parent.appendChild(i);i.x=x;i.y=y;return i;}
async function button(p,label,x,y,w=358,h=52,name){const bc=await figma.getNodeByIdAsync('1:25');const b=bc.createInstance();p.appendChild(b);b.x=x;b.y=y;try{b.resize(w,h)}catch(e){}const ts=b.findAll(n=>n.type==='TEXT');if(ts[0])ts[0].characters=label;ts.forEach(t=>{try{t.fontName={family:'Poppins',style:'Medium'};t.fills=[{type:'SOLID',color:WHITE}]}catch(e){}});if(name)b.name=name;return b;}
